 * Prefix index over Unicode strings.
 *
 * Words are stored in a real trie: one node per distinct prefix, walked by
 * Unicode code point, with a per-node count of the words stored below it.
 */

/** A single trie node. */
class TrieNode {
  /** @type {Map<number, TrieNode>} Children keyed by code point. */
  children = new Map();

  /** @type {boolean} Whether a word ends here. */
  hasValue = false;

  /** @type {unknown} Value stored at this node. */
  value = undefined;

  /** @type {number} Number of stored words at or below this node. */
  count = 0;
}

/**
 * Asserts that a value is a string.
 * @param {unknown} value Value to check.
 * @param {string} name Argument name used in the error message.
 * @returns {string} The value, narrowed to a string.
 */
function requireString(value, name) {
  if (typeof value !== 'string') throw new TypeError(`${name} must be a string`);
  return value;
}

/**
 * Asserts that a limit is Infinity or a non-negative safe integer.
 * @param {unknown} limit Value to check.
 * @returns {number} The validated limit.
 */
function requireLimit(limit) {
  if (limit === Number.POSITIVE_INFINITY) return limit;
  if (typeof limit !== 'number' || !Number.isSafeInteger(limit) || limit < 0) {
    throw new TypeError('limit must be a non-negative integer');
  }
  return limit;
}

/**
 * Splits a string into its code points.
 * @param {string} text Text to split.
 * @returns {number[]} Code points in order.
 */
function codePoints(text) {
  const out = [];
  for (const character of text) out.push(character.codePointAt(0));
  return out;
}

export class Trie {
  /** @type {TrieNode} */
  #root = new TrieNode();

  /** @type {number} */
  #nodeCount = 1;

  /** @returns {number} Number of stored words. */
  get size() {
    return this.#root.count;
  }

  /** @returns {number} Number of nodes, the root included. */
  get nodeCount() {
    return this.#nodeCount;
  }

  /**
   * Walks to the node for a string without creating anything.
   * @param {number[]} points Code points to follow.
   * @returns {TrieNode | undefined} The node, or undefined when absent.
   */
  #find(points) {
    let node = this.#root;
    for (const point of points) {
      const next = node.children.get(point);
      if (next === undefined) return undefined;
      node = next;
    }
    return node;
  }

  /**
   * Stores a value under a word, replacing any value already there.
   * @param {string} word Word to store.
   * @param {unknown} value Value to associate.
   * @returns {unknown} Previously stored value, or undefined when the word is new.
   */
  insert(word, value) {
    const points = codePoints(requireString(word, 'word'));
    const path = [this.#root];
    let node = this.#root;
    for (const point of points) {
      let next = node.children.get(point);
      if (next === undefined) {
        next = new TrieNode();
        node.children.set(point, next);
        this.#nodeCount += 1;
      }
      node = next;
      path.push(node);
    }
    if (node.hasValue) {
      const previous = node.value;
      node.value = value;
      return previous;
    }
    node.hasValue = true;
    node.value = value;
    for (const step of path) step.count += 1;
    return undefined;
  }

  /**
   * Reads the value stored under a word.
   * @param {string} word Word to look up.
   * @returns {unknown} Stored value, or undefined when the word is absent.
   */
  get(word) {
    const node = this.#find(codePoints(requireString(word, 'word')));
    return node !== undefined && node.hasValue ? node.value : undefined;
  }

  /**
   * Reports whether a word is stored.
   * @param {string} word Word to look up.
   * @returns {boolean} True when the word is stored.
   */
  has(word) {
    const node = this.#find(codePoints(requireString(word, 'word')));
    return node !== undefined && node.hasValue;
  }

  /**
   * Removes a word and any nodes it alone kept alive.
   * @param {string} word Word to remove.
   * @returns {boolean} True when a word was removed.
   */
  delete(word) {
    const points = codePoints(requireString(word, 'word'));
    const path = [this.#root];
    let node = this.#root;
    for (const point of points) {
      const next = node.children.get(point);
      if (next === undefined) return false;
      node = next;
      path.push(node);
    }
    if (!node.hasValue) return false;
    node.hasValue = false;
    node.value = undefined;
    for (const step of path) step.count -= 1;
    for (let i = path.length - 1; i > 0; i -= 1) {
      const current = path[i];
      if (current.count !== 0 || current.children.size !== 0) break;
      path[i - 1].children.delete(points[i - 1]);
      this.#nodeCount -= 1;
    }
    return true;
  }

  /**
   * Counts the stored words that start with a prefix.
   * @param {string} prefix Prefix to count under.
   * @returns {number} Number of words with that prefix.
   */
  countPrefix(prefix) {
    const node = this.#find(codePoints(requireString(prefix, 'prefix')));
    return node === undefined ? 0 : node.count;
  }

  /**
   * Collects words below a node in code point order.
   * @param {TrieNode} node Subtree root.
   * @param {string} prefix Prefix that reaches the node.
   * @param {number} limit Maximum number of results.
   * @param {Array<[string, unknown]>} out Accumulator.
   * @returns {void}
   */
  #collect(node, prefix, limit, out) {
    if (out.length >= limit) return;
    if (node.hasValue) {
      out.push([prefix, node.value]);
      if (out.length >= limit) return;
    }
    const keys = [...node.children.keys()].sort((a, b) => a - b);
    for (const key of keys) {
      this.#collect(node.children.get(key), prefix + String.fromCodePoint(key), limit, out);
      if (out.length >= limit) return;
    }
  }

